#[derive(Debug, Clone)]
pub struct ParsedExpression {
    pub class: u64,
    pub type_: u64,
    pub alias: String,
    pub query_location: Option<u64>,
    pub query_location_length: Option<u32>,
    pub kind: ParsedExpressionKind,
}

#[derive(Debug, Clone)]
pub enum ParsedExpressionKind {
    BetweenExpression(BetweenExpression),
    CaseExpression(CaseExpression),
    CastExpression(CastExpression),
    CollateExpression(CollateExpression),
    ColumnRefExpression(ColumnRefExpression),
    LambdaRefExpression(LambdaRefExpression),
    ComparisonExpression(ComparisonExpression),
    ConjunctionExpression(ConjunctionExpression),
    ConstantExpression(ConstantExpression),
    DefaultExpression(DefaultExpression),
    FunctionExpression(FunctionExpression),
    LambdaExpression(LambdaExpression),
    OperatorExpression(OperatorExpression),
    ParameterExpression(ParameterExpression),
    PositionalReferenceExpression(PositionalReferenceExpression),
    StarExpression(StarExpression),
    SubqueryExpression(SubqueryExpression),
    WindowExpression(WindowExpression),
    TypeExpression(TypeExpression),
}

impl ParsedExpression {
    pub fn read_members(d: &mut BinaryDeserializer<'_>) -> Result<Self> {
        let class = d.read_property::<u64>(100, "class")?;
        let type_ = d.read_property::<u64>(101, "type")?;
        let alias = d.read_property_with_default::<String>(102, "alias")?;
        let query_location = d.read_optional_property::<u64>(103, "query_location")?;
        let query_location_length = d.read_optional_property::<u32>(104, "query_location_length")?;
        let kind = match u64::from(class) {
            enums::expression_class::BETWEEN => {
                ParsedExpressionKind::BetweenExpression(BetweenExpression::read_members(d)?)
            }
            enums::expression_class::CASE => ParsedExpressionKind::CaseExpression(CaseExpression::read_members(d)?),
            enums::expression_class::CAST => ParsedExpressionKind::CastExpression(CastExpression::read_members(d)?),
            enums::expression_class::COLLATE => {
                ParsedExpressionKind::CollateExpression(CollateExpression::read_members(d)?)
            }
            enums::expression_class::COLUMN_REF => {
                ParsedExpressionKind::ColumnRefExpression(ColumnRefExpression::read_members(d)?)
            }
            enums::expression_class::LAMBDA_REF => {
                ParsedExpressionKind::LambdaRefExpression(LambdaRefExpression::read_members(d)?)
            }
            enums::expression_class::COMPARISON => {
                ParsedExpressionKind::ComparisonExpression(ComparisonExpression::read_members(d)?)
            }
            enums::expression_class::CONJUNCTION => {
                ParsedExpressionKind::ConjunctionExpression(ConjunctionExpression::read_members(d)?)
            }
            enums::expression_class::CONSTANT => {
                ParsedExpressionKind::ConstantExpression(ConstantExpression::read_members(d)?)
            }
            enums::expression_class::DEFAULT => {
                ParsedExpressionKind::DefaultExpression(DefaultExpression::read_members(d)?)
            }
            enums::expression_class::FUNCTION => {
                ParsedExpressionKind::FunctionExpression(FunctionExpression::read_members(d)?)
            }
            enums::expression_class::LAMBDA => {
                ParsedExpressionKind::LambdaExpression(LambdaExpression::read_members(d)?)
            }
            enums::expression_class::OPERATOR => {
                ParsedExpressionKind::OperatorExpression(OperatorExpression::read_members(d)?)
            }
            enums::expression_class::PARAMETER => {
                ParsedExpressionKind::ParameterExpression(ParameterExpression::read_members(d)?)
            }
            enums::expression_class::PATTERN => return Err(not_ported("MATCH_RECOGNIZE patterns")),
            enums::expression_class::POSITIONAL_REFERENCE => {
                ParsedExpressionKind::PositionalReferenceExpression(PositionalReferenceExpression::read_members(d)?)
            }
            enums::expression_class::STAR => ParsedExpressionKind::StarExpression(StarExpression::read_members(d)?),
            enums::expression_class::SUBQUERY => {
                ParsedExpressionKind::SubqueryExpression(SubqueryExpression::read_members(d)?)
            }
            enums::expression_class::WINDOW => {
                ParsedExpressionKind::WindowExpression(WindowExpression::read_members(d)?)
            }
            enums::expression_class::TYPE => ParsedExpressionKind::TypeExpression(TypeExpression::read_members(d)?),
            other => return Err(unknown("ParsedExpression", other)),
        };
        Ok(Self {
            class,
            type_,
            alias,
            query_location,
            query_location_length,
            kind,
        })
    }

    pub fn write_members(&self, s: &mut BinarySerializer) {
        s.write_property(100, "class", &self.class);
        s.write_property(101, "type", &self.type_);
        s.write_property_with_default(102, "alias", &self.alias);
        s.write_optional_property(103, "query_location", self.query_location.as_ref());
        if s.should_serialize(StorageVersion::V2_0_0) {
            s.write_optional_property(104, "query_location_length", self.query_location_length.as_ref());
        }
        match &self.kind {
            ParsedExpressionKind::BetweenExpression(value) => value.write_members(s),
            ParsedExpressionKind::CaseExpression(value) => value.write_members(s),
            ParsedExpressionKind::CastExpression(value) => value.write_members(s),
            ParsedExpressionKind::CollateExpression(value) => value.write_members(s),
            ParsedExpressionKind::ColumnRefExpression(value) => value.write_members(s),
            ParsedExpressionKind::LambdaRefExpression(value) => value.write_members(s),
            ParsedExpressionKind::ComparisonExpression(value) => value.write_members(s),
            ParsedExpressionKind::ConjunctionExpression(value) => value.write_members(s),
            ParsedExpressionKind::ConstantExpression(value) => value.write_members(s),
            ParsedExpressionKind::DefaultExpression(value) => value.write_members(s),
            ParsedExpressionKind::FunctionExpression(value) => value.write_members(s),
            ParsedExpressionKind::LambdaExpression(value) => value.write_members(s),
            ParsedExpressionKind::OperatorExpression(value) => value.write_members(s),
            ParsedExpressionKind::ParameterExpression(value) => value.write_members(s),
            ParsedExpressionKind::PositionalReferenceExpression(value) => value.write_members(s),
            ParsedExpressionKind::StarExpression(value) => value.write_members(s),
            ParsedExpressionKind::SubqueryExpression(value) => value.write_members(s),
            ParsedExpressionKind::WindowExpression(value) => value.write_members(s),
            ParsedExpressionKind::TypeExpression(value) => value.write_members(s),
        }
    }
}

impl Deserialize for ParsedExpression {
    fn read_value(d: &mut BinaryDeserializer<'_>) -> Result<Self> {
        d.read_object_value(Self::read_members)
    }
}

impl Serialize for ParsedExpression {
    fn write_value(&self, s: &mut BinarySerializer) {
        s.write_object_value(|s| self.write_members(s));
    }
}

